def _get_tokenizer(self) -> Any:
    """Get the tokenizer from the processor info."""
    vllm_tokenizer = self.info.get_tokenizer()
    tokenizer = vllm_tokenizer.custom_tokenizer

    if hasattr(tokenizer, "_original_encode"):
        return tokenizer

    original_encode = tokenizer.encode
    tokenizer._original_encode = original_encode

    def patched_encode(
        text: str,
        bos: bool = False,
        eos: bool = False,
        allowed_special: str | None = None,
        **kwargs: Any,
    ) -> list[int]:
        if allowed_special is not None:
            return original_encode(
                text, bos=bos, eos=eos, allowed_special="all", **kwargs
            )
        return original_encode(text, bos=bos, eos=eos, **kwargs)

    tokenizer.encode = patched_encode
    return tokenizer

