    parallel config via ``moe_config.moe_parallel_config`` rather than as a
    direct attribute.
    """
    cfg = getattr(layer, "moe_parallel_config", None)
    if cfg is not None:
        return cfg
    moe_config = getattr(layer, "moe_config", None)
    if moe_config is not None:
        return getattr(moe_config, "moe_parallel_config", None)
    return None


def _layer_enable_eplb(layer) -> bool:
    if hasattr(layer, "enable_eplb"):
