def _select_experts(layer, hidden_states, router_logits):
    """Compute (topk_weights, topk_ids) for the custom-routed MoE.

    Older vLLM exposed ``layer.router.select_experts``; newer vLLM passes the
    RoutedExperts submodule as ``layer``, which carries the model's
    ``custom_routing_function`` directly. Call it to obtain the pre-computed
    routing consumed by the flashinfer routed kernels.
    """
    router = getattr(layer, "router", None)
    if router is not None and hasattr(router, "select_experts"):
        return router.select_experts(
            hidden_states=hidden_states,
            router_logits=router_logits,
        )
    return layer.custom_routing_function(
        hidden_states=hidden_states,
        gating_output=router_logits,
        topk=layer.top_k,
        renormalize=True,
    )


