def select_unquantized_moe_backend(
    moe_config: FusedMoEConfig,
) -> tuple[UnquantizedMoeBackend, type[mk.FusedMoEExperts] | None]:
    """
    Select the primary Unquantized MoE backend.
    Note: Shape-specific fallbacks may still occur at runtime.
    """

    if current_platform.is_tpu():
        return UnquantizedMoeBackend.TPU, None

    if current_platform.is_out_of_tree():
        return UnquantizedMoeBackend.OOT, None

    if moe_config.is_lora_enabled:
        if _trtllm_bf16_lora_supported(moe_config):
            from vllm.model_executor.layers.fused_moe.experts.trtllm_lora_moe import (
                TrtLlmBf16LoRAExperts,
            )

            logger.info_once(
                "Using TrtLlmBf16LoRAExperts Unquantized MoE LoRA backend "
                "(TrtLlmBf16LoRAExperts)."
            )
            return UnquantizedMoeBackend.FLASHINFER_TRTLLM, TrtLlmBf16LoRAExperts
        logger.info_once("Using TRITON Unquantized MoE LoRA backend")
        return UnquantizedMoeBackend.TRITON, backend_to_kernel_cls(
            UnquantizedMoeBackend.TRITON
        )[0]

    # NOTE: the kernels are selected in the following order.
    AVAILABLE_BACKENDS = _get_priority_backends(moe_config)

    # NOTE(rob): We need to peak into the P/F selection to determine
    # if we are using the batched or standard expert format, which
    # if not ideal. Once we unify TP + DP/EP, we can select P/F first.
    activation_format = (
        mk.FusedMoEActivationFormat.BatchedExperts
        if moe_config.moe_parallel_config.use_batched_activation_format
        or moe_config.moe_backend == "batched_triton"
        else mk.FusedMoEActivationFormat.Standard
    )

    def _make_log_backend(backend: UnquantizedMoeBackend) -> str:
        available_strs = [b.value for b in AVAILABLE_BACKENDS]
        return (
            f"Using {backend.value} Unquantized MoE backend out "
            f"of potential backends: {available_strs}."
        )

    def _make_log_unsupported(
        backend: UnquantizedMoeBackend, reason: str | None
    ) -> str:
        if reason:
            return (
                f"Unquantized MoE backend {backend.value} does not support the "
                f"deployment configuration since {reason}."
            )
        return (
            f"Unquantized MoE backend '{backend.value}' does not support the "
            "deployment configuration."
        )

    def _return_or_raise(
        backend: UnquantizedMoeBackend,
        config: FusedMoEConfig,
        activation_format: mk.FusedMoEActivationFormat,
    ) -> tuple[UnquantizedMoeBackend, type[mk.FusedMoEExperts] | None]:
        reason = None
        for k_cls in backend_to_kernel_cls(backend):
            supported, reason = k_cls.is_supported_config(
                k_cls, config, None, None, activation_format
            )
            if supported:
                logger.info_once(_make_log_backend(backend))
                return backend, k_cls
        raise ValueError(_make_log_unsupported(backend, reason))

    runner_backend = moe_config.moe_backend
    # 'humming' is quantization-only; an unquantized layer (e.g. excluded via
    # modules_to_not_convert) falls through to auto instead of erroring.
    if runner_backend not in ["auto", "humming"]:
        requested_backend = map_unquantized_backend(runner_backend)
        if (
            activation_format == mk.FusedMoEActivationFormat.BatchedExperts
            and requested_backend == UnquantizedMoeBackend.TRITON
        ):
            requested_backend = UnquantizedMoeBackend.BATCHED_TRITON

        return _return_or_raise(requested_backend, moe_config, activation_format)

    # Handle explicit AITER FP8 configuration.
    if envs.is_set("VLLM_ROCM_USE_AITER") or envs.is_set("VLLM_ROCM_USE_AITER_MOE"):
        skip_aiter_moe = (
            not envs.VLLM_ROCM_USE_AITER
            or not envs.VLLM_ROCM_USE_AITER_MOE
            or rocm_aiter_ops.is_rdna_aiter_enabled()
        )
        if skip_aiter_moe:
            if UnquantizedMoeBackend.AITER in AVAILABLE_BACKENDS:
                AVAILABLE_BACKENDS.remove(UnquantizedMoeBackend.AITER)
        else:
            backend = UnquantizedMoeBackend.AITER
            return _return_or_raise(backend, moe_config, activation_format)

    for backend in AVAILABLE_BACKENDS:
        for k_cls in backend_to_kernel_cls(backend):
            supported, reason = k_cls.is_supported_config(
                k_cls, moe_config, None, None, activation_format
            )
            if supported:
                logger.info_once(_make_log_backend(backend))
                return backend, k_cls

def apply_with_post_norm_context(
    self, layer, x, topk_weights, topk_ids, *args, **kwargs
):
    post_expert_norm_fn = getattr(layer, "post_expert_norm_fn", None)
    # Get weight lazily from module reference for fused kernel mode
    post_expert_norm_module = getattr(layer, "post_expert_norm_module", None)
    post_expert_norm_weight = (
        post_expert_norm_module.weight.data
        if post_expert_norm_module is not None
        else None
    )

    if post_expert_norm_fn is None and post_expert_norm_weight is None:
        return original_apply(
            self, layer, x, topk_weights, topk_ids, *args, **kwargs
        )

    # Check for CUTLASS BF16 (unquantized) backend — use the dedicated
    # do_finalize=False path with per-expert RMSNorm.
    has_old_qm = hasattr(self, "old_quant_method")
    has_unq_backend = has_old_qm and hasattr(
        self.old_quant_method, "unquantized_backend"
    )
    unq_backend = (
        self.old_quant_method.unquantized_backend if has_unq_backend else None
    )
    is_cutlass_bf16 = unq_backend == UnquantizedMoeBackend.FLASHINFER_CUTLASS
    if post_expert_norm_fn is not None and is_cutlass_bf16:
        post_expert_norm_weight_p1 = getattr(
            layer, "_post_expert_norm_weight_p1", None
        )
        return run_fi_cutlass_moe_bf16_with_post_norm(
            self,
            layer,
            x,
            topk_weights,
            topk_ids,
            post_expert_norm_fn,
            post_expert_norm_weight if VLLM_FUSE_POST_EXPERT_NORM else None,
            post_expert_norm_weight_p1,
        )

    tokens = []
    if post_expert_norm_fn is not None:
        tokens.append(("fn", _post_expert_norm_fn_ctx.set(post_expert_norm_fn)))
    if post_expert_norm_weight is not None and VLLM_FUSE_POST_EXPERT_NORM:
        tokens.append(
            ("weight", _post_expert_norm_weight_ctx.set(post_expert_norm_weight))
        )
    try:
        return original_apply(
            self, layer, x, topk_weights, topk_ids, *args, **kwargs
        )
    finally:
        for token_type, token in tokens:
            if token_type == "fn":
                _post_expert_norm_fn_ctx.reset(token)
            else:
                _post_expert_norm_weight_ctx.reset(token)

