def patch_modelopt_nvfp4_apply_monolithic():
    """
    Patch ModelOptNvFp4FusedMoE.apply_monolithic to support
    calling post_expert_norm_fn for trtllm moe (NVFP4 checkpoint).
    """

    from vllm.model_executor.layers.fused_moe.config import RoutingMethodType

    # Patch routing method to accept Custom so monolithic expert is selected
    # for musespark1x models (which use CustomRoutingRouter / RoutingMethodType.Custom).
    # Without this, the modular expert is selected, is_monolithic returns False,
    # and the apply_monolithic post-norm patch below never fires.
    #
    # newer vLLM refactored into experts/ subpackage; older vLLM keeps the
    # module-level function in flashinfer_fp4_moe (different signature).
    try:
        from vllm.model_executor.layers.fused_moe.experts.trtllm_nvfp4_moe import (
            TrtLlmNvFp4ExpertsMonolithic,
        )

        original_supports_routing_method = (
            TrtLlmNvFp4ExpertsMonolithic._supports_routing_method
        )

        @staticmethod  # type: ignore[misc]
        def patched_supports_routing_method(
            routing_method_type: RoutingMethodType,
            weight_key=None,
            activation_key=None,
        ) -> bool:
            if routing_method_type == RoutingMethodType.Custom:
                return True
            return original_supports_routing_method(
                routing_method_type, weight_key, activation_key
            )

        TrtLlmNvFp4ExpertsMonolithic._supports_routing_method = (
            patched_supports_routing_method  # type: ignore[assignment]
        )
    except (ImportError, ModuleNotFoundError):
        # older vLLM: patch module-level _supports_routing_method
        # in flashinfer_fp4_moe (old signature: routing_method only).
        try:
            import vllm.model_executor.layers.quantization.utils.flashinfer_fp4_moe as _fi_fp4_mod

            original_supports_routing_method = _fi_fp4_mod._supports_routing_method

            def patched_supports_routing_method_legacy(
                routing_method: RoutingMethodType,
            ) -> bool:
                if routing_method == RoutingMethodType.Custom:
                    return True
                return original_supports_routing_method(routing_method)

            _fi_fp4_mod._supports_routing_method = (
                patched_supports_routing_method_legacy
            )
        except (ImportError, AttributeError) as exc:
            raise ImportError(
                "Neither trtllm_nvfp4_moe nor "
                "flashinfer_fp4_moe._supports_routing_method available "
                "for NvFP4 routing method patching"
            ) from exc

    from vllm.model_executor.layers.quantization.modelopt import ModelOptNvFp4FusedMoE
    from vllm_muse_spark.plugins.moe_post_norm_fi_trtllm import (
        run_fi_trtllm_moe_nvfp4_with_post_norm,
    )

    original_apply_monolithic = ModelOptNvFp4FusedMoE.apply_monolithic

    def apply_monolithic_with_post_norm_context(
        self, layer, x, router_logits, *args, **kwargs
    ):
        post_expert_norm_fn = getattr(layer, "post_expert_norm_fn", None)
        # Get weight lazily from module reference to avoid accessing during init
        post_expert_norm_module = getattr(layer, "post_expert_norm_module", None)
        post_expert_norm_weight = (
            post_expert_norm_module.weight.data
            if post_expert_norm_module is not None and VLLM_FUSE_POST_EXPERT_NORM
            else None
        )
        # Pre-computed weight + 1.0 for CuTeDSL kernel
        post_expert_norm_weight_p1 = getattr(layer, "_post_expert_norm_weight_p1", None)
        # Compute + cache lazily when only the norm module was propagated to this
        # layer (newer vLLM passes the RoutedExperts submodule, and the model's
        # load_weights precompute runs on the FusedMoE wrapper instead).
        if (
            post_expert_norm_weight_p1 is None
            and post_expert_norm_module is not None
            and VLLM_FUSE_POST_EXPERT_NORM
        ):
            _w = post_expert_norm_module.weight.data
            post_expert_norm_weight_p1 = (_w.float() + 1.0).to(_w.dtype)
            layer._post_expert_norm_weight_p1 = post_expert_norm_weight_p1

        if post_expert_norm_fn is None:
            return original_apply_monolithic(
                self, layer, x, router_logits, *args, **kwargs
            )

        return run_fi_trtllm_moe_nvfp4_with_post_norm(
            self,
            layer,
            x,
            router_logits,
            post_expert_norm_fn,
            post_expert_norm_weight,
            post_expert_norm_weight_p1,
        )

    ModelOptNvFp4FusedMoE.apply_monolithic = apply_monolithic_with_post_norm_context

