{%- endmacro -%}

{%- macro esc_header(value) -%}
    {{- esc(value) | replace('\r', ' ') | replace('\n', ' ') -}}
{%- endmacro -%}

{%- macro esc_attr(value) -%}
    {{- esc_header(value)
        | replace('&', '&amp;')
        | replace('"', '&quot;')
        | replace("'", '&#39;')
        | replace('<', '&lt;')
        | replace('>', '&gt;') -}}
{%- endmacro -%}

{%- macro render_content(content) -%}
    {%- if content is string -%}
        {{- esc(content | trim) -}}
    {%- elif content is not none -%}
        {%- for part in content -%}
