    ZERO = "zero"  # gain center is 0.0
    INVERSE_RESIDUAL_INDEX_V2 = "inverse_residual_index_v2"  # 1 / (residual_id + 1)
    INVERSE_RESIDUAL_INDEX_P1 = "inverse_residual_index_p1"  # Same as INVERSE_RESIDUAL_INDEX_V2. Added for backward compatibility.
    INVERSE_RESIDUAL_INDEX = "inverse_residual_index"  # 1 / (2 * layer_id)
    INVERSE_SQRT_RESIDUAL_INDEX = (
        "inverse_sqrt_residual_index"  # 1 / sqrt(2 * layer_id)
    )
    INVERSE_SQRT_LAYERS = "inverse_sqrt_layers"  # 1 / sqrt(n_layers)


def calculate_gain_center(
    gain_center_type: str,
    residual_id: int,
    n_layers: int | None = None,
) -> float:
    """Calculate the gain center value based on the type and layer ID.

    Args:
        gain_center_type: Type of gain center calculation strategy
        residual_id: Current residual ID (1-indexed)
        n_layers: (Optional) Total layers in model.

    Returns:
        Calculated gain center value.
    """
    gain_center = GainCenter(gain_center_type)
    if gain_center == GainCenter.ONE:
        return 1.0
    elif gain_center == GainCenter.ZERO:
        return 0.0
    elif gain_center == GainCenter.INVERSE_RESIDUAL_INDEX:
        return 1.0 / (2 * math.ceil(residual_id / 2))
    elif gain_center in [
        GainCenter.INVERSE_RESIDUAL_INDEX_V2,
        GainCenter.INVERSE_RESIDUAL_INDEX_P1,
    ]:
        return 1.0 / (residual_id + 1)
    elif gain_center == GainCenter.INVERSE_SQRT_RESIDUAL_INDEX:
        return 1.0 / math.sqrt(2 * math.ceil(residual_id / 2))
    elif gain_center == GainCenter.INVERSE_SQRT_LAYERS:
        assert n_layers is not None, "n_layers must be provided for this option."
        return 1.0 / math.sqrt(n_layers)
    else:
        raise ValueError(f"Unsupported gain_center_type: {gain_center_type}")

