        components[component] = loaded_weight
        if all(part in components for part in expected):
            fused = torch.cat([components.pop(part) for part in expected], dim=0)
            pending.pop(prefix, None)
            yield f"{prefix}.qkv_proj.weight", fused

    if fuse_qkvo and pending:
        missing_by_layer = {
            prefix: [part for part in expected if part not in components]
            for prefix, components in pending.items()
        }
        raise ValueError(
            "Incomplete MuseSpark1x gated-attention q/k/v/o_gate weights: "
            f"{missing_by_layer}"
        )

