def patch_routed_experts_forward_publish_post_norm() -> None:
    """Publish the norm from the one place every MoE backend funnels through.

    The patches above wrap the ``apply`` of specific quantization methods. On 0.28
    each method defines its own ``apply``, so that only covers the methods named --
    and MXFP4 (``CompressedTensorsW4A4Mxfp4MoEMethod``, the method this checkpoint
    selects on XPU) is not one of them. On that path the norm was published nowhere
    and the XPU consumer read an empty context variable, i.e. the model served
    unnormalised expert output.

    ``RoutedExperts.forward_modular`` and ``forward_monolithic`` are the only
    callers of ``quant_method.apply`` / ``apply_monolithic``, and ``self`` there is
    the ``RoutedExperts`` the norm is mirrored onto, so wrapping these two covers
    every backend -- quantized or not, modular or monolithic -- without naming any
    of them.
    """
    from vllm.model_executor.layers.fused_moe.routed_experts import RoutedExperts

    def make_publisher(original):
        def forward_with_post_norm_context(self, *args, **kwargs):
            post_expert_norm_fn = getattr(self, "post_expert_norm_fn", None)
            post_expert_norm_module = getattr(self, "post_expert_norm_module", None)
            post_expert_norm_weight = (
                post_expert_norm_module.weight.data
                if post_expert_norm_module is not None
                else None
            )
            if post_expert_norm_fn is None and post_expert_norm_weight is None:
                return original(self, *args, **kwargs)

            tokens = []
            if post_expert_norm_fn is not None:
                tokens.append(
                    (
                        _post_expert_norm_fn_ctx,
                        _post_expert_norm_fn_ctx.set(post_expert_norm_fn),
                    )
                )
            if post_expert_norm_weight is not None and VLLM_FUSE_POST_EXPERT_NORM:
                tokens.append(
                    (
                        _post_expert_norm_weight_ctx,
                        _post_expert_norm_weight_ctx.set(post_expert_norm_weight),
                    )
                )
            weight_p1 = getattr(self, "_post_expert_norm_weight_p1", None)
            if weight_p1 is not None:
                tokens.append(
                    (
                        _post_expert_norm_weight_p1_ctx,
                        _post_expert_norm_weight_p1_ctx.set(weight_p1),
                    )
                )
            try:
                return original(self, *args, **kwargs)
            finally:
                for ctx_var, token in tokens:
                    ctx_var.reset(token)

        forward_with_post_norm_context._musespark1x_post_norm_publisher = True
        forward_with_post_norm_context._musespark1x_original = original
        return forward_with_post_norm_context

    for method_name in ("forward_modular", "forward_monolithic"):
        original = getattr(RoutedExperts, method_name)
        if getattr(original, _POST_NORM_PUBLISHER_FLAG, False):
            continue
        setattr(RoutedExperts, method_name, make_publisher(original))
        logger.info(
            "Patched RoutedExperts.%s to publish the post-expert norm", method_name
        )


